const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Sierra Nevada region
  const sierraNevada = ee.Geometry.Polygon([
    [-120.5, 38.0],
    [-119.0, 38.0], 
    [-118.0, 37.0],
    [-119.5, 36.0],
    [-121.0, 36.5],
    [-121.0, 38.0]
  ]);

  // Define the three specific dates
  const dates = [
    {name: 'Jan1', date: '2022-01-01'},
    {name: 'Apr1', date: '2022-04-01'}, 
    {name: 'May4', date: '2022-05-04'}
  ];

  const results = {};

  // Process each date
  for (const dateInfo of dates) {
    const collection = ee.ImageCollection('MODIS/061/MOD10A1')
      .filterBounds(sierraNevada)
      .filterDate(dateInfo.date, ee.Date(dateInfo.date).advance(1, 'day'));

    const size = collection.size().getInfo();
    console.log(`${dateInfo.name} Images: ${size}`);

    if (size === 0) {
      console.log(`<answer>C1</answer>`);
      return;
    }

    // Get the first (only) image for that date
    const image = collection.first();

    // Get snow cover band and mask non-snow values (values > 100 are clouds/water/no data)
    const snowCover = image.select('NDSI_Snow_Cover')
      .updateMask(image.select('NDSI_Snow_Cover').lte(100));

    // Count valid pixels
    const pixelCount = snowCover.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: sierraNevada,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDSI_Snow_Cover').getInfo();

    console.log(`${dateInfo.name} Valid Pixels: ${pixelCount}`);

    if (pixelCount === 0) {
      console.log(`<answer>C2</answer>`);
      return;
    }

    // Calculate mean snow cover percentage
    const meanSnow = snowCover.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: sierraNevada,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDSI_Snow_Cover').getInfo();

    console.log(`${dateInfo.name} Mean Snow Cover: ${meanSnow ? meanSnow.toFixed(1) : 'null'}%`);

    results[dateInfo.name] = meanSnow;
  }

  // Validate results
  if (results.Jan1 === null || results.Apr1 === null || results.May4 === null) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if Jan 1 has more snow than both Apr 1 AND May 4
  const janGreaterThanApr = results.Jan1 > results.Apr1;
  const janGreaterThanMay = results.Jan1 > results.May4;

  console.log(`Jan > Apr: ${janGreaterThanApr}, Jan > May: ${janGreaterThanMay}`);

  if (janGreaterThanApr && janGreaterThanMay) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
